logs.push(log);
fs.writeFileSync(logPath, JSON.stringify(logs, null, 2));
console.log('Short guardado: ' + upload.url);

return [{ json: { mensaje: 'Short EP' + upload.episodio + ' ' + upload.short_name + ' publicado', url: upload.url, titulo: upload.titulo } }];
